CREATE TABLE subscription_plans (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), key text NOT NULL UNIQUE, deactivated_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE subscription_plan_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), subscription_plan_id uuid NOT NULL REFERENCES subscription_plans(id), version_number integer NOT NULL CHECK (version_number > 0), name text NOT NULL, currency char(3) NOT NULL, amount_minor bigint NOT NULL CHECK (amount_minor >= 0), cadence text NOT NULL CHECK (cadence IN ('monthly', 'annual')), provider_plan_reference text, effective_from timestamptz NOT NULL DEFAULT now(), effective_to timestamptz, created_at timestamptz NOT NULL DEFAULT now(), CHECK (effective_to IS NULL OR effective_to > effective_from), UNIQUE(subscription_plan_id, version_number));
CREATE TABLE customer_subscriptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_profile_id uuid NOT NULL REFERENCES customer_profiles(id), subscription_plan_version_id uuid NOT NULL REFERENCES subscription_plan_versions(id), status text NOT NULL CHECK (status IN ('pending', 'active', 'past_due', 'grace', 'cancelled')), provider_subscription_reference text, started_at timestamptz, renewal_at timestamptz, cancelled_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX customer_subscriptions_customer_idx ON customer_subscriptions (customer_profile_id, status);
CREATE FUNCTION reject_subscription_plan_version_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Subscription plan versions are immutable.'; END; $$;
CREATE TRIGGER subscription_plan_versions_immutable BEFORE UPDATE OR DELETE ON subscription_plan_versions FOR EACH ROW EXECUTE FUNCTION reject_subscription_plan_version_mutation();
